import json,re,sys

HEADER = 'daemon off;\nworker_processes 1;\npid @ROOT@/nginx.pid;\nerror_log @ROOT@/error.log;\nevents { worker_connections 64; }\nhttp {\n access_log off;\n client_body_temp_path @ROOT@/client_body;\n proxy_temp_path @ROOT@/proxy_temp;\n fastcgi_temp_path @ROOT@/fastcgi_temp;\n uwsgi_temp_path @ROOT@/uwsgi_temp;\n scgi_temp_path @ROOT@/scgi_temp;\n'

def render(routes):
    if not isinstance(routes,list) or not 1<=len(routes)<=16:raise ValueError('1..16 routes required')
    seen=set()
    for route in routes:
        if not isinstance(route,dict) or set(route)!={'prefix','mode','port'}:raise ValueError('route schema')
        prefix=route['prefix']
        if not isinstance(prefix,str) or len(prefix)>120 or not re.fullmatch(r'/(?:[a-z][a-z0-9_-]*/)+',prefix):raise ValueError('literal path prefix')
        if prefix in seen:raise ValueError('duplicate prefix')
        seen.add(prefix)
        if route['mode'] not in ('strip','keep'):raise ValueError('mode')
        if type(route['port']) is not int or not 1024<=route['port']<=65535:raise ValueError('loopback unprivileged port')
    lines=[]
    for route in sorted(routes,key=lambda r:r['prefix']):
        suffix='/'
        lines.append(' location '+route['prefix']+' { proxy_pass http://127.0.0.1:'+str(route['port'])+suffix+'; }\n')
    return HEADER+' server { listen 127.0.0.1:@PORT@;\n'+''.join(lines)+' location / { return 404; }\n}\n}\n'

def unique(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError('duplicate JSON key')
        result[key]=value
    return result

if __name__=='__main__':
    try:
        if len(sys.argv)!=2:raise ValueError('usage: render.py routes.json')
        with open(sys.argv[1],encoding='utf8') as f:routes=json.load(f,object_pairs_hook=unique)
        print(render(routes),end='')
    except (ValueError,TypeError,OSError,RecursionError) as error:
        print(str(error),file=sys.stderr);sys.exit(2)

